#include <boost/multiprecision/cpp_int.hpp>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <string>

int main(int argc, char* argv[]) {
    if (argc < 2) return 1;

    char* end = nullptr;
    const unsigned long long n = std::strtoull(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0' || n == 0) return 1;

    using boost::multiprecision::cpp_int;

    cpp_int numerator = 1;
    cpp_int accumulator = 0;
    cpp_int denominator = 1;
    cpp_int probe, quotient, remainder, product;

    std::string output;
    unsigned long long produced = 0;
    unsigned column = 0;

    // Unbounded linear-fractional spigot: consume terms until the
    // lower and upper bounds agree on the next decimal digit.
    for (std::uint64_t k = 1; produced < n; ++k) {
        const std::uint64_t factor = 2 * k + 1;

        probe = numerator;
        probe <<= 1;
        accumulator += probe;
        accumulator *= factor;
        denominator *= factor;
        numerator *= k;

        if (accumulator < numerator) continue;

        probe = numerator * 3;
        probe += accumulator;
        quotient = probe / denominator;
        const unsigned digit = quotient.convert_to<unsigned>();

        product = denominator * digit;
        remainder = probe - product;
        remainder += numerator;

        if (remainder >= denominator) continue;

        output.push_back(static_cast<char>('0' + digit));
        ++produced;
        ++column;

        if (column == 10 || produced == n) {
            output.append(10 - column, ' ');
            output += "\t:";
            output += std::to_string(produced);
            output.push_back('\n');
            column = 0;
        }

        if (produced == n) break;

        accumulator -= product;
        accumulator *= 10;
        numerator *= 10;
    }

    std::fwrite(output.data(), 1, output.size(), stdout);
    return 0;
}

